            check = "update",
            custom = "function()\n    -- Only update every 1 second\n    if not aura_env.lastUpdate or (GetTime() - aura_env.lastUpdate) >= 1 then\n        aura_env.lastUpdate = GetTime()\n        \n        local text = \"\"\n        local numGroupMembers = GetNumGroupMembers()\n        \n        -- Function to extract AP bonus from tooltip\n        local function GetAPBonus(unit)\n            local apBonus = 0\n            \n            for i = 1, 40 do\n                local nameBuff = UnitBuff(unit, i)\n                if not nameBuff then break end\n                \n                if nameBuff == \"Battle Shout\" then\n                    -- Use the reusable tooltip\n                    local tooltip = aura_env.tooltip\n                    tooltip:ClearLines()\n                    tooltip:SetUnitBuff(unit, i)\n                    \n                    -- Scan tooltip lines for AP bonus\n                    for j = 2, tooltip:NumLines() do\n                        local line = _G[tooltip:GetName() .. \"TextLeft\" .. j]\n                        if line then\n                            local textLine = line:GetText()\n                            if textLine then\n                                -- Try matching both patterns\n                                local ap = string.match(textLine, \"Increases your melee attack power by (%d+)\") or string.match(textLine, \"Attack power increased by (%d+)\")\n                                if ap then\n                                    apBonus = tonumber(ap)\n                                    break\n                                end\n                            end\n                        end\n                    end\n                    \n                    -- Break out of the loop after processing Battle Shout\n                    break\n                end\n            end\n            \n            return apBonus\n        end\n        \n        -- Function to get colored AP text\n        local function GetColoredAPText(apBonus)\n            if apBonus >= 290 then\n                -- Green color for AP >= 290\n                return \"|cFF00FF00\" .. apBonus .. \" AP|r\"\n            else\n                -- Red color for AP < 290\n                return \"|cFFFF0000\" .. apBonus .. \" AP|r\"\n            end\n        end\n        \n        -- Function to get \"BS missing\" text\n        local function GetMissingText()\n            return \"BS missing\"\n        end\n        \n        -- Function to get class-colored name\n        local function GetClassColoredName(unit)\n            local name = UnitName(unit) or \"Unknown\"\n            local _, classFileName = UnitClass(unit)\n            if classFileName then\n                local classColor = RAID_CLASS_COLORS[classFileName]\n                if classColor then\n                    local colorCode = string.format(\"%02X%02X%02X%02X\", 255, classColor.r * 255, classColor.g * 255, classColor.b * 255)\n                    return \"|c\" .. colorCode .. name .. \"|r\"\n                end\n            end\n            return name\n        end\n        \n        -- Function to check if unit's class is Warrior or Rogue\n        local function IsDesiredClass(unit)\n            local _, classFileName = UnitClass(unit)\n            return classFileName == \"WARRIOR\" or classFileName == \"ROGUE\"\n        end\n        \n        -- Get player's raid group number\n        local playerGroup = 0\n        local playerName = UnitName(\"player\")\n        if IsInRaid() then\n            for i = 1, numGroupMembers do\n                local name, _, subgroup = GetRaidRosterInfo(i)\n                if name and name == playerName then\n                    playerGroup = subgroup\n                    break\n                end\n            end\n        end\n        \n        -- Loop through raid units\n        if IsInRaid() then\n            for i = 1, numGroupMembers do\n                local unit = \"raid\" .. i\n                if UnitExists(unit) and not UnitIsUnit(unit, \"player\") and IsDesiredClass(unit) then\n                    local name, _, subgroup = GetRaidRosterInfo(i)\n                    if subgroup == playerGroup then\n                        local coloredName = GetClassColoredName(unit)\n                        local apBonus = GetAPBonus(unit)\n                        \n                        if apBonus > 0 then\n                            local coloredAPText = GetColoredAPText(apBonus)\n                            text = text .. coloredName .. \": \" .. coloredAPText .. \"\\n\"\n                        else\n                            local missingText = GetMissingText()\n                            text = text .. coloredName .. \": \" .. missingText .. \"\\n\"\n                        end\n                    end\n                end\n            end\n        elseif IsInGroup() then\n            for i = 1, numGroupMembers - 1 do\n                local unit = \"party\" .. i\n                if UnitExists(unit) and IsDesiredClass(unit) then\n                    local coloredName = GetClassColoredName(unit)\n                    local apBonus = GetAPBonus(unit)\n                    \n                    if apBonus > 0 then\n                        local coloredAPText = GetColoredAPText(apBonus)\n                        text = text .. coloredName .. \": \" .. coloredAPText .. \"\\n\"\n                    else\n                        local missingText = GetMissingText()\n                        text = text .. coloredName .. \": \" .. missingText .. \"\\n\"\n                    end\n                end\n            end\n        end\n        \n        -- Include the player if they are Warrior or Rogue\n        local playerUnit = \"player\"\n        if IsDesiredClass(playerUnit) then\n            local playerNameColored = GetClassColoredName(playerUnit)\n            local playerAPBonus = GetAPBonus(playerUnit)\n            \n            if playerAPBonus > 0 then\n                local coloredAPText = GetColoredAPText(playerAPBonus)\n                text = playerNameColored .. \": \" .. coloredAPText .. \"\\n\" .. text\n            else\n                local missingText = GetMissingText()\n                text = playerNameColored .. \": \" .. missingText .. \"\\n\" .. text\n            end\n        else\n            -- If the player is not one of the desired classes, do not include them\n            text = text\n        end\n        \n        -- Store the result in aura_env\n        aura_env.displayText = text\n    end\n    \n    return true\nend",
